(function(){"use strict";var refocusNew=false;function isCell(el){return el&&el.classList&&el.classList.contains("cell")&&!el.classList.contains("cell--new");}
function cells(){return Array.prototype.filter.call(document.querySelectorAll("input.cell"),function(el){return!el.disabled&&el.offsetParent!==null;});}
function mark(input,ok){input.removeAttribute("aria-busy");input.classList.toggle("is-invalid",!ok);if(ok){input.removeAttribute("aria-invalid");input.classList.add("is-saved");setTimeout(function(){input.classList.remove("is-saved");},1600);}else{input.setAttribute("aria-invalid","true");}}
function save(input){var form=input.form;if(!form||!window.htmx)return;var values={campo:input.name};values[input.name]=input.value;Array.prototype.forEach.call(form.elements,function(el){if(el.type==="hidden"&&el.name)values[el.name]=el.value;});input.setAttribute("aria-busy","true");window.htmx.ajax("POST",form.getAttribute("action"),{source:input,values:values,swap:"none"});}
var TRANSPORT_MSG={0:"Sem conexão: não salvou. Confira a internet e saia do campo de novo.",400:"A página expirou: não salvou. Recarregue a página e digite de novo.",429:"Muitas tentativas seguidas: não salvou. Espere um pouco e saia do campo de novo.",500:"Erro no servidor: não salvou. Tente de novo em instantes."};function explainFailure(xhr){var code=xhr?xhr.status:0;if(code===401&&xhr.getResponseHeader("HX-Redirect"))return;if(xhr&&/id="salvo-status"/.test(xhr.responseText||""))return;var status=document.getElementById("salvo-status");if(!status)return;status.textContent=TRANSPORT_MSG[code]||(code>=500?TRANSPORT_MSG[500]:"Não salvou. Recarregue a página e tente de novo.");status.classList.add("save-status--error");status.setAttribute("role","alert");}
document.addEventListener("htmx:afterRequest",function(event){var input=event.target;if(!isCell(input))return;var xhr=event.detail&&event.detail.xhr;var ok=!!(xhr&&xhr.status>=200&&xhr.status<300);if(ok)input.setAttribute("data-orig",input.value);mark(input,ok);if(!ok)explainFailure(xhr);});document.addEventListener("focusin",function(event){var input=event.target;if(isCell(input)&&!input.hasAttribute("aria-busy")){if(!input.hasAttribute("data-orig"))input.setAttribute("data-orig",input.defaultValue);}});document.addEventListener("keydown",function(event){var input=event.target;if(!isCell(input))return;if(event.key==="Enter"){event.preventDefault();var all=cells();var next=all[all.indexOf(input)+1];if(next){next.focus();if(next.select)next.select();}else{input.blur();}}else if(event.key==="Escape"){event.preventDefault();input.value=input.getAttribute("data-orig")||"";input.classList.remove("is-invalid");input.removeAttribute("aria-invalid");input.blur();}});document.addEventListener("focusout",function(event){var input=event.target;if(isCell(input)){var orig=input.hasAttribute("data-orig")?input.getAttribute("data-orig"):input.defaultValue;if(input.value!==orig)save(input);return;}
if(input&&input.classList&&input.classList.contains("cell--new")){var row=input.closest("tr");setTimeout(function(){if(row&&row.contains(document.activeElement))return;var name=document.getElementById("nova-nome");var form=document.getElementById("f-nova");if(name&&form&&name.value.trim()){refocusNew=true;form.requestSubmit();}},0);}});document.addEventListener("htmx:afterSettle",function(){if(!refocusNew)return;refocusNew=false;var name=document.getElementById("nova-nome");if(name&&!name.value)name.focus();});document.addEventListener("submit",function(event){if(event.target&&event.target.matches&&event.target.matches("[data-new-form]"))refocusNew=true;});document.addEventListener("change",function(event){var form=event.target&&event.target.closest?event.target.closest("form[data-autosubmit]"):null;if(form)form.requestSubmit();});})();